#include <gtest/gtest.h>

extern "C" {
#include "core/types/base.h"
#include "core/types/tier_position_hash_set.h"
}

// ====================== Initialization and Destruction ======================

// Verifies that standard initialization with a nominal load factor results in
// an empty set.
TEST(TierPositionHashSetTest, StandardInitialization) {
    TierPositionHashSet set;
    TierPositionHashSetInit(&set, 0.65);

    EXPECT_EQ(TierPositionHashSetGetSize(&set), 0)
        << "Expected a newly initialized set to have a size of 0.";

    TierPositionHashSetDestroy(&set);
}

// Verifies that initialization safely handles load factors below the valid
// [0.5, 0.8] range. Note: We cannot directly assert the internal load factor
// clamping here without exposing internal state, so we verify the set
// initializes into a valid, usable empty state.
TEST(TierPositionHashSetTest, ClampsLowerBoundLoadFactor) {
    TierPositionHashSet set;
    TierPositionHashSetInit(&set, 0.2);

    EXPECT_EQ(TierPositionHashSetGetSize(&set), 0)
        << "Expected initialization to succeed despite an artificially low "
           "load factor.";

    TierPositionHashSetDestroy(&set);
}

// Verifies that initialization safely handles load factors above the valid
// [0.5, 0.8] range.
TEST(TierPositionHashSetTest, ClampsUpperBoundLoadFactor) {
    TierPositionHashSet set;
    TierPositionHashSetInit(&set, 0.95);

    EXPECT_EQ(TierPositionHashSetGetSize(&set), 0)
        << "Expected initialization to succeed despite an artificially high "
           "load factor.";

    TierPositionHashSetDestroy(&set);
}

// Verifies that destroying an empty, freshly initialized set completes without
// memory faults. Destructor logic often branches depending on whether internal
// buffers were allocated yet.
TEST(TierPositionHashSetTest, DestroysEmptySetSafely) {
    TierPositionHashSet set;
    TierPositionHashSetInit(&set, 0.65);

    TierPositionHashSetDestroy(&set);
    SUCCEED()
        << "Expected destruction of an empty set to complete without crashing.";
}

// Verifies that destroying a set with active allocations/elements cleans up
// without faulting.
TEST(TierPositionHashSetTest, DestroysPopulatedSetSafely) {
    TierPositionHashSet set;
    TierPositionHashSetInit(&set, 0.65);

    TierPositionHashSetAdd(&set, {1, 100});
    TierPositionHashSetAdd(&set, {2, 200});
    TierPositionHashSetAdd(&set, {3, 300});

    ASSERT_EQ(TierPositionHashSetGetSize(&set), 3)
        << "Expected set size to reflect the successfully added elements "
           "before destruction.";

    TierPositionHashSetDestroy(&set);
    SUCCEED() << "Expected destruction of a populated set to complete without "
                 "crashing.";
}

// =========================== Insertion and Lookup ===========================

// Verifies that adding a new, valid key to the set returns true and increments
// the size.
TEST(TierPositionHashSetTest, AddSingleElement) {
    TierPositionHashSet set;
    TierPositionHashSetInit(&set, 0.65);

    EXPECT_TRUE(TierPositionHashSetAdd(&set, {1, 100}))
        << "Expected Add to return true for a newly inserted element.";
    EXPECT_EQ(TierPositionHashSetGetSize(&set), 1)
        << "Expected size to increment to 1 after a successful insertion.";

    TierPositionHashSetDestroy(&set);
}

// Verifies that a successfully added key can be reliably retrieved via
// Contains.
TEST(TierPositionHashSetTest, ContainsExistingKey) {
    TierPositionHashSet set;
    TierPositionHashSetInit(&set, 0.65);

    TierPositionHashSetAdd(&set, {1, 100});

    EXPECT_TRUE(TierPositionHashSetContains(&set, {1, 100}))
        << "Expected Contains to return true for a key that was previously "
           "added.";

    TierPositionHashSetDestroy(&set);
}

// Verifies that querying a key not present in a populated set correctly returns
// false. This ensures that lookups correctly distinguish between occupied
// buckets containing different keys and the actual target key.
TEST(TierPositionHashSetTest, ContainsMissingKey) {
    TierPositionHashSet set;
    TierPositionHashSetInit(&set, 0.65);

    TierPositionHashSetAdd(&set, {1, 100});

    EXPECT_FALSE(TierPositionHashSetContains(&set, {2, 200}))
        << "Expected Contains to return false for a key that was never added.";

    TierPositionHashSetDestroy(&set);
}

// Verifies that lookups on a brand-new, empty set safely return false without
// crashing. Empty sets might lack allocated underlying buffers, so early-exit
// logic must be sound.
TEST(TierPositionHashSetTest, ContainsOnEmptySet) {
    TierPositionHashSet set;
    TierPositionHashSetInit(&set, 0.65);

    EXPECT_FALSE(TierPositionHashSetContains(&set, {1, 100}))
        << "Expected Contains to return false when querying a completely empty "
           "set.";

    TierPositionHashSetDestroy(&set);
}

// Verifies that the set adheres to mathematical set properties by rejecting
// duplicate keys.
TEST(TierPositionHashSetTest, AddDuplicateKey) {
    TierPositionHashSet set;
    TierPositionHashSetInit(&set, 0.65);

    TierPosition key = {1, 100};

    EXPECT_TRUE(TierPositionHashSetAdd(&set, key))
        << "Expected the initial insertion to succeed.";
    EXPECT_FALSE(TierPositionHashSetAdd(&set, key))
        << "Expected subsequent insertions of the exact same key to return "
           "false.";
    EXPECT_EQ(TierPositionHashSetGetSize(&set), 1)
        << "Expected size to remain unaffected by rejected duplicate "
           "insertions.";

    TierPositionHashSetDestroy(&set);
}

// Verifies that consecutive insertions of unique keys are successfully
// recorded.
TEST(TierPositionHashSetTest, AddMultipleUniqueKeys) {
    TierPositionHashSet set;
    TierPositionHashSetInit(&set, 0.65);

    constexpr int kNumElements = 100;
    for (int i = 0; i < kNumElements; ++i) {
        // Incrementing position ensures each key is strictly unique
        EXPECT_TRUE(TierPositionHashSetAdd(&set, {1, static_cast<Position>(i)}))
            << "Expected Add to return true for unique key where position = "
            << i << ".";
    }

    EXPECT_EQ(TierPositionHashSetGetSize(&set), kNumElements)
        << "Expected total size to match the exact number of unique "
           "insertions.";

    TierPositionHashSetDestroy(&set);
}

// ===================== Capacity Management and Expansion =====================

// Verifies that requesting to reserve space for fewer elements than the current
// capacity acts as a safe no-op. This ensures we don't accidentally shrink or
// unnecessarily reallocate underlying buffers.
TEST(TierPositionHashSetTest, ReserveSufficientCapacity) {
    TierPositionHashSet set;
    TierPositionHashSetInit(&set, 0.65);

    // Establish an initial capacity.
    ASSERT_TRUE(TierPositionHashSetReserve(&set, 100))
        << "Expected initial reservation to succeed.";

    // Request a smaller size than what was already reserved.
    EXPECT_TRUE(TierPositionHashSetReserve(&set, 50))
        << "Expected reserve to return true immediately when capacity is "
           "already sufficient.";

    TierPositionHashSetDestroy(&set);
}

// Verifies that upfront capacity reservation correctly allocates memory.
// Pre-allocating is critical for performance to avoid amortized reallocation
// costs during bulk insertions.
TEST(TierPositionHashSetTest, ReserveTriggersExpansion) {
    TierPositionHashSet set;
    TierPositionHashSetInit(&set, 0.65);

    // Reserve a significantly large capacity.
    EXPECT_TRUE(TierPositionHashSetReserve(&set, 1000000))
        << "Expected reserve to successfully allocate space for 1,000,000 "
           "elements.";

    // Verify the set is still functionally valid.
    EXPECT_TRUE(TierPositionHashSetAdd(&set, {1, 100}))
        << "Expected insertion to succeed after a massive capacity expansion.";

    TierPositionHashSetDestroy(&set);
}

// Verifies that the library fails gracefully rather than crashing if an
// allocation request exceeds system limits or integer bounds.
TEST(TierPositionHashSetTest, ReserveHandlesAllocationFailure) {
    TierPositionHashSet set;
    TierPositionHashSetInit(&set, 0.65);

    // Request an impossibly large capacity to simulate an OOM/overflow
    // scenario.
    EXPECT_FALSE(TierPositionHashSetReserve(&set, INT64_MAX))
        << "Expected reserve to return false when memory allocation inevitably "
           "fails.";

    TierPositionHashSetDestroy(&set);
}

// Verifies that the set automatically rehashes and expands its backing array
// when the load factor threshold is breached via standard insertions.
TEST(TierPositionHashSetTest, AutomaticExpansionOnAdd) {
    TierPositionHashSet set;
    // A low load factor forces expansions to happen sooner.
    TierPositionHashSetInit(&set, 0.5);

    constexpr int kElements = 10000;

    for (int i = 0; i < kElements; ++i) {
        ASSERT_TRUE(TierPositionHashSetAdd(&set, {1, static_cast<Position>(i)}))
            << "Expected Add to succeed; auto-expansion should handle "
               "underlying allocations.";
    }

    EXPECT_EQ(TierPositionHashSetGetSize(&set), kElements)
        << "Expected set size to accurately reflect all elements after "
           "multiple rehashes.";

    // Validates that elements weren't lost or corrupted during the rehashing
    // process.
    for (int i = 0; i < kElements; ++i) {
        EXPECT_TRUE(
            TierPositionHashSetContains(&set, {1, static_cast<Position>(i)}))
            << "Expected key to survive internal expansions and rehashing "
               "(position: "
            << i << ").";
    }

    TierPositionHashSetDestroy(&set);
}

// ========================== Edge Cases and Extremes ==========================

// Verifies that a zero-filled key is processed correctly.
// This ensures the internal hashing logic doesn't conflate a key of zeroes
// with an uninitialized memory state or evaluate it to a degenerate hash.
TEST(TierPositionHashSetTest, ZeroValues) {
    TierPositionHashSet set;
    TierPositionHashSetInit(&set, 0.65);

    TierPosition zero_key = {0, 0};

    EXPECT_TRUE(TierPositionHashSetAdd(&set, zero_key))
        << "Expected Add to succeed for a key with tier 0 and position 0.";
    EXPECT_TRUE(TierPositionHashSetContains(&set, zero_key))
        << "Expected Contains to find the inserted zero-value key.";

    TierPositionHashSetDestroy(&set);
}

// Verifies that maximum integer bounds do not cause unexpected overflows
// inside the hash function or probing sequence math.
TEST(TierPositionHashSetTest, MaximumValues) {
    TierPositionHashSet set;
    TierPositionHashSetInit(&set, 0.65);

    TierPosition max_key = {INT64_MAX, INT64_MAX};

    EXPECT_TRUE(TierPositionHashSetAdd(&set, max_key))
        << "Expected Add to succeed for maximum integer values.";
    EXPECT_TRUE(TierPositionHashSetContains(&set, max_key))
        << "Expected Contains to find the maximum integer key.";

    TierPositionHashSetDestroy(&set);
}

// Verifies the boundary condition directly adjacent to the sentinel value.
// Since INT64_MIN is reserved to denote empty slots, we must ensure INT64_MIN +
// 1 is treated as a strictly valid, regular key.
TEST(TierPositionHashSetTest, NearSentinelTier) {
    TierPositionHashSet set;
    TierPositionHashSetInit(&set, 0.65);

    TierPosition near_sentinel_key = {INT64_MIN + 1, 100};

    EXPECT_TRUE(TierPositionHashSetAdd(&set, near_sentinel_key))
        << "Expected Add to succeed for a tier value exactly one above the "
           "sentinel.";
    EXPECT_TRUE(TierPositionHashSetContains(&set, near_sentinel_key))
        << "Expected Contains to find the near-sentinel key.";

    TierPositionHashSetDestroy(&set);
}

// =============================== Stress Tests ===============================

// Inserting a massive volume of elements forces the table to repeatedly rehash
// and organically triggers bucket collisions. This stress-tests the load factor
// thresholds and linear probing fallback without coupling to the black-box hash
// implementation. Note: 65,536 elements of 16 bytes (Tier + Position) equates
// to ~1 MiB of payload data.
TEST(TierPositionHashSetTest, StressAutoExpansion) {
    TierPositionHashSet set;
    TierPositionHashSetInit(&set, 0.65);

    const int32_t kNumElements = 65536;

    // Phase 1: Mass insertion.
    for (int32_t i = 0; i < kNumElements; ++i) {
        // Varying the tier slightly prevents artificial best-case clustering if
        // the hash function relies heavily on the tier component.
        ASSERT_TRUE(TierPositionHashSetAdd(&set, {i % 16, i}))
            << "Expected Add to succeed during mass insertion at iteration "
            << i << ".";
    }

    EXPECT_EQ(TierPositionHashSetGetSize(&set), kNumElements)
        << "Expected set size to exactly match the " << kNumElements
        << " unique insertions.";

    // Phase 2: Mass retrieval to guarantee no data was orphaned during
    // expansions.
    for (int32_t i = 0; i < kNumElements; ++i) {
        EXPECT_TRUE(TierPositionHashSetContains(&set, {i % 16, i}))
            << "Expected element to be found after multiple full-table "
               "rehashes (position: "
            << i << ").";
    }

    TierPositionHashSetDestroy(&set);
}

// Pre-reserving memory tests the translation between user-requested item count
// and internal bucket capacity (accounting for the load factor limit). This
// validates that the table can sustain a massive influx of elements without
// mid-run allocations.
TEST(TierPositionHashSetTest, StressWithReserve) {
    TierPositionHashSet set;
    TierPositionHashSetInit(&set, 0.65);

    const int32_t kNumElements = 65536;

    ASSERT_TRUE(TierPositionHashSetReserve(&set, kNumElements))
        << "Expected upfront reservation for " << kNumElements
        << " elements to succeed.";

    // Phase 1: Mass insertion into pre-allocated memory.
    for (int32_t i = 0; i < kNumElements; ++i) {
        ASSERT_TRUE(TierPositionHashSetAdd(&set, {i % 16, i}))
            << "Expected Add to succeed into the pre-reserved capacity at "
               "iteration "
            << i << ".";
    }

    EXPECT_EQ(TierPositionHashSetGetSize(&set), kNumElements)
        << "Expected set size to exactly match the total insertions.";

    // Phase 2: Mass retrieval to ensure the densely packed pre-allocated table
    // correctly handles the high volume of organic linear probing collisions.
    for (int32_t i = 0; i < kNumElements; ++i) {
        EXPECT_TRUE(TierPositionHashSetContains(&set, {i % 16, i}))
            << "Expected element to be found within the pre-allocated table "
               "(position: "
            << i << ").";
    }

    TierPositionHashSetDestroy(&set);
}
